#include "stdafx.h"#include "..\MnemoWnd.h"#include "Queue.h"#include "..\Lang.h"#include "Basis21.h"#include "PipeTrends.h"#include <string>#include <algorithm>typedef struct : public SPROLOZ  {  CPipeTrends* file;  COLORREF colorTxt;  char Descriptions[TREND_NUMBER][256];  STrendGroup Trends;  //  } Queue_TegscnTrends;//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Функция очистки памятиvoid ClearTegscnTrends(SQueue& q,void* s)  {  Queue_TegscnTrends* p = (Queue_TegscnTrends*)s;  if ( p->file )    delete p->file;  }void DwrawGrid(HDC hDC, RECT &rectIn, COLORREF LineColor, int nColumn, int nRow){   CMyPen pen(hDC, LineColor, 1);    double dY=(rectIn.bottom-rectIn.top)/(double)nRow;   double dX=(rectIn.right-rectIn.left)/(double)nColumn;   double x=rectIn.left;   for(int ii=0; ii<(nColumn+1); ii++)    {	  ::MoveToEx(hDC, (int)x, rectIn.top, NULL);	  ::LineTo(hDC, (int)x, rectIn.bottom);	  x+=dX;    }   double y=rectIn.top;   for(int ii=0; ii<(nRow+1); ii++)    {	  ::MoveToEx(hDC, rectIn.left, (int)y, NULL);	  ::LineTo(hDC, rectIn.right, (int)y);	  y+=dY;    }}// Функция отображенияint PaintTegscnTrends(DefinePaint){  QueueP(Queue_TegscnTrends);  //  RECT rc(p->mRect);  DOUBLE dCurrentData=0.;  DOUBLE dMax=0., dMin=0.;  STrendGroup &TrendGrp = p->Trends;  int nRow=4;  DwrawGrid(hDC, TrendGrp.rcTrend, RGB(200,200,200), 4, nRow);  //числа на шкале  COLORREF old = ::SetTextColor( hDC, TrendGrp.item[0].color );  double dY=(rc.bottom-rc.top)/(double)nRow;  int x=rc.left;  double y=rc.bottom-10;  char str[128];  double vol=TrendGrp.item->dMin;  double dvol=(TrendGrp.item->dMax-TrendGrp.item->dMin)/nRow;  for(int ii=0; ii < (nRow+1); ii++)     {      RECT rect(rc);      rect.top=(int)y;      rect.bottom=rect.top+30;      rect.right=TrendGrp.rcTrend.left-2;      sprintf_s(str, "%0.2f", vol);      ::DrawText( hDC, str, -1, &rect, DT_SINGLELINE|DT_TOP|DT_RIGHT );      y-=dY;      vol+=dvol;     }  time_t duration=DrawTrends(hDC, TrendGrp.rcTrend, p->file, TrendGrp.item, TrendGrp.tm, TrendGrp.bVertical, true, TrendGrp.nPenSize,                              TrendGrp.colorTxt, TrendGrp.nTimers, TrendGrp.rcTextTime);  ::SetTextColor( hDC, TrendGrp.colorTxt );  char text[128];  __time64_t tModel=GiveModelTime();  int nTimeSdvig=TrendGrp.tm/(TrendGrp.nTimers-1);  __time64_t t[11];  for (int i=TrendGrp.nTimers-1;i>=0;i--)	{	    t[i]=tModel;	    tModel-=nTimeSdvig;	}  for (int i=0;i<TrendGrp.nTimers;i++)	{	    RECT rect = TrendGrp.rcTextTime[i];	    RECT rectEnd=TrendGrp.rcTextTime[i];        struct tm Tm;        _localtime64_s( &Tm, &t[i] );        strftime( text, _countof(text)-1, "%H:%M\n%d:%m:%Y", &Tm );	    int nLength=lstrlen(text);	    ::DrawText( hDC, text, nLength, &rect, DT_WORDBREAK | DT_TOP | DT_CENTER);	}  ::SetTextColor( hDC, old );  return 1;}void AddTegscnTrends(DefineTegs){  //  AddQueueEx(Queue_TegscnTrends);  // Код, посылаемый в АРМ  p->btSendType = QUEUE_NO;  // Определение функции вывода  p->paint = &PaintTegscnTrends;  // Функция очистки памяти  p->clear = &ClearTegscnTrends;  //  p->colorTxt= RGB(0,0,0);   p->file=NULL;  p->Trends.nTimers=3;  p->Trends.tm=3600;  //  STegObj obj[] =    {    { 'R', "rect", &p->mRect },    { 'E', "rc"  , &p->mRect },    { 'I', "duration", &p->Trends.tm},    };  ::ParserObjScn( teg, obj, sizeof(obj)/sizeof(STegObj) );  //    if(p->Trends.tm < 60)      p->Trends.tm=3600;    p->Trends.nItemCount=1;    strcpy_s(p->Trends.ValueRealName[0], teg[0].value);    STrendGroup &tg = p->Trends;     int leftMargin=60;    int rightMargin=90;      tg.rcTrend=p->mRect;    tg.rcTrend.left+=leftMargin;    tg.rcTrend.right-=rightMargin;    p->file=NULL;    p->file = new CPipeTrends();    if( p->file != NULL )       {        //инициализация для трендов          if (!tg.bVertical)	         p->file->SetPoint(tg.rcTrend.right-tg.rcTrend.left);          else  p->file->SetPoint(abs(tg.rcTrend.bottom-tg.rcTrend.top));          for(int ii=0; ii<tg.nItemCount; ii++)            {            tg.nTags[ii] = ::FindTagEx( tg.ValueRealName[ii], id_Sensor );  //в файле DATA\ACY\tegs.scn            tg.item[ii].dMin=tg.dRealMins[ii]=0.;            tg.item[ii].dMax=tg.dRealMaxs[ii]=100.;            tg.item[ii].color = RGB(0,0,255);            SFromTrend* trend = p->file->From();            p->file->Add(p->Trends.ValueRealName[ii]);            tg.item[ii].data = p->file->Data(ii);            if(tg.nTags[ii]>=0)              {               char *ref=(char*)::TegValueS( tg.nTags[ii], "Unit", "");               if(ref)                 strcpy_s(tg.Units[ii], ref);               tg.item[ii].dMin=tg.dRealMins[ii]=::TegValueD( tg.nTags[ii], "min", 0.);               tg.item[ii].dMax=tg.dRealMaxs[ii]=::TegValueD( tg.nTags[ii], "max", 100.);               tg.dL[ii] = ::TegValueD( tg.nTags[ii], "L", -DBL_MAX/2 );               tg.dH[ii] = ::TegValueD( tg.nTags[ii], "H", DBL_MAX/2 );                tg.dLL[ii] = ::TegValueD( tg.nTags[ii], "LL", -DBL_MAX/2 );               tg.dHH[ii] = ::TegValueD( tg.nTags[ii], "HH", DBL_MAX/2 );                  ref = (char*)::TegValueS( tg.nTags[ii], "DESC", "");               if(ref)                 strcpy_s(p->Descriptions[ii], ref);               ref = (char*)::TegValueS( tg.nTags[ii], "Color", "#FF0000");               if(ref)                 tg.item[ii].color = ::ParserColors( ref );              }           }      }  double dLength=double(tg.rcTrend.right-tg.rcTrend.left)/(tg.nTimers-1);  int hh=40;  for (int i=0;i<tg.nTimers;i++)  {      tg.rcTextTime[i].top=tg.rcTrend.bottom+10;      tg.rcTextTime[i].bottom=tg.rcTextTime[i].top+hh;	  tg.rcTextTime[i].left=int(tg.rcTrend.left+i*dLength-dLength/2.);	  tg.rcTextTime[i].right=int(tg.rcTextTime[i].left+dLength);  }}